-- 把 kst-remove-some-readings.sql 删掉的九月读数放回去（由删除前的实际资料生成，2026-09-11）。可以重跑：先删同一批再插回。
SET NOCOUNT ON;
DELETE e FROM dbo.zSCP2_MeterEntry e JOIN dbo.zSCP2_ItemMeter m ON m.ItemMeterKey=e.ItemMeterKey JOIN dbo.zSCP2_Item i ON i.ItemKey=m.ItemKey JOIN dbo.zSCP2_Contract c ON c.ContractKey=i.ContractKey WHERE c.ContractNo=N'DEMO-KST' AND e.PeriodYear=2026 AND e.PeriodMonth=9 AND e.InvoicedDocKey IS NULL AND ((i.ServiceItemNo IN (N'DEMO-KST-005',N'DEMO-KST-006',N'DEMO-KST-007',N'DEMO-KST-015',N'DEMO-KST-016',N'DEMO-KST-024')) OR (i.ServiceItemNo=N'DEMO-KST-002' AND m.MeterRole=N'CL'));
